fn find_max(a: &[i32], n: usize) -> usize {
    // Ensure n is within bounds (though problem states it's guaranteed)
    let prefix = &a[..n];
    
    // Find the maximum value in the prefix
    let max_value = prefix.iter().max().unwrap();
    
    // Find the first index where this maximum value occurs
    prefix.iter().position(|&x| x == *max_value).unwrap()
}

// Alternative implementation that finds the index directly without separate max_value
fn find_max_alternative(a: &[i32], n: usize) -> usize {
    let prefix = &a[..n];
    
    // Find index of maximum value in one pass
    let mut max_index = 0;
    let mut max_value = prefix[0];
    
    for (i, &value) in prefix.iter().enumerate().skip(1) {
        if value > max_value {
            max_value = value;
            max_index = i;
        }
    }
    
    max_index
}